                  key={experience.id}
                  className="flex flex-col sm:flex-row items-start gap-4 sm:gap-6"
                  data-testid={`option-${experience.id}`}
                >
                  <Button
                    size="lg"
                    variant={experience.id === "unit-operation-simulator" ? "default" : "secondary"}
