                  </div>
                  <div className="text-sm text-foreground pt-5 text-center">XXX</div>
                </div>
              </CardContent>
            </Card>

            {/* Configuration */}
            <Card>
              <CardContent className="pt-6 space-y-4">
                <div>
                  <Label className="text-sm">Number of Random Samples:</Label>
                  <Input
