                  {/* Statistics */}
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <p className="font-semibold">5% Conf. Interval</p>
                      <p className="text-muted-foreground" data-testid="text-profit-5-conf">
