                <div className="grid grid-cols-[140px_1fr] items-center gap-3">
                  <Label className="text-sm">N2 %:</Label>
                  <Input
                    value={n2Percent}
                    onChange={(e) => setN2Percent(e.target.value)}
                    placeholder="--"
