type EditableField = keyof Omit<ProcessTag, 'id' | 'createdAt' | 'updatedAt'>;

const columns: { key: EditableField; label: string; width: string }[] = [
  { key: 'tagName', label: 'Tag Name', width: '120px' },
  { key: 'description', label: 'Description', width: '200px' },
  { key: 'area', label: 'Area', width: '100px' },
  { key: 'loopType', label: 'Loop Type', width: '100px' },
  { key: 'pvUnit', label: 'Unit', width: '60px' },
  { key: 'rangeLow', label: 'Range Low', width: '80px' },
  { key: 'rangeHigh', label: 'Range High', width: '80px' },
  { key: 'typicalSp', label: 'Typical SP', width: '80px' },
  { key: 'alarmHH', label: 'Alarm HH', width: '80px' },
  { key: 'alarmH', label: 'Alarm H', width: '80px' },
  { key: 'alarmL', label: 'Alarm L', width: '80px' },
  { key: 'alarmLL', label: 'Alarm LL', width: '80px' },
  { key: 'controlMode', label: 'Control Mode', width: '80px' },
  { key: 'controllerOutputTo', label: 'Controller Output', width: '120px' },
  { key: 'setpointSource', label: 'SP Source', width: '100px' },
  { key: 'cascadeMaster', label: 'Cascade Master', width: '100px' },
  { key: 'failPosition', label: 'Fail Position', width: '80px' },
  { key: 'interlocksPermissives', label: 'Interlocks', width: '150px' },
  { key: 'keyNarrativeSummary', label: 'Summary', width: '200px' },
  { key: 'onHold', label: 'On Hold', width: '60px' },
  { key: 'page', label: 'Page', width: '50px' },
];

export default function InputVariables() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [editedTags, setEditedTags] = useState<Map<number, Partial<ProcessTag>>>(new Map());
  const [hasChanges, setHasChanges] = useState(false);

  const { data: tags, isLoading, refetch } = useQuery<ProcessTag[]>({
    queryKey: ["/api/process-tags"],
  });

  const seedMutation = useMutation({
    mutationFn: async () => {
      const response = await apiRequest("POST", "/api/process-tags/seed");
      return response.json();
    },
    onSuccess: (data) => {
      toast({ title: "Database Seeded", description: data.message });
      queryClient.invalidateQueries({ queryKey: ["/api/process-tags"] });
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: number; data: Partial<ProcessTag> }) => {
      const response = await apiRequest("PATCH", `/api/process-tags/${id}`, data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/process-tags"] });
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const deleteAllMutation = useMutation({
    mutationFn: async () => {
      const response = await apiRequest("DELETE", "/api/process-tags");
      return response.json();
    },
    onSuccess: () => {
      toast({ title: "All Tags Deleted", description: "You can now reseed the data." });
      queryClient.invalidateQueries({ queryKey: ["/api/process-tags"] });
      setEditedTags(new Map());
      setHasChanges(false);
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const handleCellChange = (tagId: number, field: EditableField, value: string) => {
    setEditedTags(prev => {
      const newMap = new Map(prev);
      const existing = newMap.get(tagId) || {};
      newMap.set(tagId, { ...existing, [field]: value });
      return newMap;
    });
    setHasChanges(true);
  };

  const getCellValue = (tag: ProcessTag, field: EditableField): string => {
    const editedValue = editedTags.get(tag.id)?.[field];
    if (editedValue !== undefined) {
      return String(editedValue);
    }
    const originalValue = tag[field];
    return originalValue !== null ? String(originalValue) : '';
  };

  const handleSaveAll = async () => {
    const entries = Array.from(editedTags.entries());
    let successCount = 0;
    let failedIds: number[] = [];

    for (const [id, data] of entries) {
      try {
        await updateMutation.mutateAsync({ id, data });
        successCount++;
        setEditedTags(prev => {
          const newMap = new Map(prev);
          newMap.delete(id);
          return newMap;
        });
      } catch (error) {
        failedIds.push(id);
      }
    }

    if (failedIds.length === 0) {
      setHasChanges(false);
      toast({ title: "Changes Saved", description: `Updated ${successCount} tag(s) successfully.` });
    } else if (successCount > 0) {
      setHasChanges(true);
      toast({ 
        title: "Partial Save", 
        description: `Saved ${successCount} tag(s). ${failedIds.length} tag(s) failed to save.`,
        variant: "destructive"
      });
    } else {
      toast({ title: "Save Failed", description: "Could not save any changes.", variant: "destructive" });
    }
  };

  const handleRefresh = () => {
    setEditedTags(new Map());
    setHasChanges(false);
    refetch();
  };

  return (
    <div className="min-h-screen bg-background flex flex-col">
      <header className="border-b border-border bg-card">
        <div className="px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setLocation("/simulation-settings")}
              data-testid="button-back-settings"
            >
              <ArrowLeft className="w-5 h-5" />
            </Button>
            <div>
              <h1 className="font-semibold text-foreground">Input Variable Ranges and Alarm Set Points</h1>
              <p className="text-xs text-muted-foreground">Configure process variables, ranges, and alarm limits</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {(!tags || tags.length === 0) && (
              <Button
                onClick={() => seedMutation.mutate()}
                disabled={seedMutation.isPending}
                data-testid="button-seed-data"
                className="gap-2"
              >
                <Database className="w-4 h-4" />
                {seedMutation.isPending ? "Seeding..." : "Load Sample Data"}
              </Button>
            )}
            {tags && tags.length > 0 && (
              <>
                <Button
                  variant="outline"
                  onClick={handleRefresh}
                  disabled={isLoading}
                  data-testid="button-refresh"
                  className="gap-2"
                >
                  <RefreshCw className="w-4 h-4" />
                  Refresh
                </Button>
                <Button
                  variant="destructive"
                  onClick={() => deleteAllMutation.mutate()}
                  disabled={deleteAllMutation.isPending}
                  data-testid="button-delete-all"
                  className="gap-2"
                >
                  <Trash2 className="w-4 h-4" />
                  Clear All
                </Button>
                <Button
                  onClick={handleSaveAll}
                  disabled={!hasChanges || updateMutation.isPending}
                  data-testid="button-save-all"
                  className="gap-2"
                >
                  <Save className="w-4 h-4" />
                  {updateMutation.isPending ? "Saving..." : "Save Changes"}
                </Button>
              </>
            )}
          </div>
        </div>
      </header>

      <main className="flex-1 p-6 overflow-hidden">
        <Card className="h-full flex flex-col">
          <CardHeader className="pb-3">
            <CardTitle>Process Tags Configuration</CardTitle>
            <CardDescription>
              {tags ? `${tags.length} tags loaded` : 'Loading...'} 
              {hasChanges && <span className="ml-2 text-yellow-600">(Unsaved changes)</span>}
            </CardDescription>
          </CardHeader>
          <CardContent className="flex-1 overflow-hidden">
            {isLoading ? (
              <div className="flex items-center justify-center h-full text-muted-foreground">
                Loading process tags...
              </div>
            ) : !tags || tags.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-muted-foreground gap-4">
                <Database className="w-16 h-16 opacity-50" />
                <p>No process tags configured yet.</p>
                <p className="text-sm">Click "Load Sample Data" to populate the table with example data.</p>
              </div>
            ) : (
              <ScrollArea className="h-[calc(100vh-280px)]">
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        {columns.map((col) => (
                          <TableHead 
                            key={col.key} 
                            style={{ minWidth: col.width }}
                            className="bg-muted/50 sticky top-0"
                          >
                            {col.label}
                          </TableHead>
                        ))}
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {tags.map((tag) => (
                        <TableRow key={tag.id} data-testid={`row-tag-${tag.id}`}>
                          {columns.map((col) => (
                            <TableCell key={col.key} className="p-1">
                              <Input
                                value={getCellValue(tag, col.key)}
                                onChange={(e) => handleCellChange(tag.id, col.key, e.target.value)}
                                className="h-8 text-xs border-transparent hover:border-border focus:border-primary"
                                data-testid={`input-${col.key}-${tag.id}`}
                              />
                            </TableCell>
                          ))}
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </ScrollArea>
            )}
          </CardContent>
        </Card>
      </main>

      <footer className="border-t border-border bg-card py-3 px-6">
        <div className="flex items-center justify-between text-xs text-muted-foreground">
          <span>Input Variables | Process Tag Configuration</span>
          <span>Lithium Americas OTS</span>
        </div>
      </footer>
    </div>
  );
}

